import type { SVGProps } from "react";

/**
 * The PathAble mark: one continuous stroke drawing a P, from an open origin
 * ring to a solid destination dot. Geometry matches public/brand/*.svg
 * (generated by scripts/build-brand.py).
 */
export function Mark({ title, ...props }: SVGProps<SVGSVGElement> & { title?: string }) {
  return (
    <svg viewBox="0 0 32 32" role={title ? "img" : undefined} aria-hidden={title ? undefined : true} {...props}>
      {title && <title>{title}</title>}
      <path d="M10 22.6V11a7 7 0 0 1 7-7a7 7 0 0 1 0 14h-2.4" fill="none" stroke="var(--brand)" strokeWidth="3.2" strokeLinecap="round" strokeLinejoin="round" />
      <circle cx="10" cy="26.2" r="2.9" fill="none" stroke="var(--brand)" strokeWidth="2.4" />
      <circle cx="13.4" cy="18" r="3.1" fill="var(--signal)" />
    </svg>
  );
}
